  /** 检查节点是否有交互后代（不含自身）。子树结论缓存：嵌套滚动容器避免重复整树扫描。 */
  private hasInteractiveDescendants(node: SimplifiedNode): boolean {
    const cached = this.interactiveDescendantsCache.get(node.originalNode.nodeId);
    if (cached !== undefined) return cached;
    let result = false;
    for (const child of node.children) {
      if (this.isInteractiveCached(child.originalNode) || this.hasInteractiveDescendants(child)) {
        result = true;
        break;
      }
    }
    this.interactiveDescendantsCache.set(node.originalNode.nodeId, result);
    return result;
  }
